#include <flint/fmpq.h>
#include <flint/fmpq_poly.h>
#include <flint/fmpq_mat.h>
#include <flint/fmpz.h>
#include <flint/fmpz_poly.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <cassert>
#include <chrono>
using namespace std;
struct Poly{fmpq_poly_struct p[1];Poly(){fmpq_poly_init(p);}Poly(const Poly&a):Poly(){fmpq_poly_set(p,a.p);}Poly(Poly&&a):Poly(){fmpq_poly_swap(p,a.p);}Poly&operator=(Poly a){fmpq_poly_swap(p,a.p);return *this;}~Poly(){fmpq_poly_clear(p);}};
struct Z{fmpz_t v;Z(){fmpz_init(v);}Z(const Z&a):Z(){fmpz_set(v,a.v);}Z(Z&&a):Z(){fmpz_swap(v,a.v);}Z&operator=(Z a){fmpz_swap(v,a.v);return *this;}~Z(){fmpz_clear(v);}};
struct ZPoly{fmpz_poly_t p;ZPoly(){fmpz_poly_init(p);}ZPoly(const ZPoly&a):ZPoly(){fmpz_poly_set(p,a.p);}ZPoly(ZPoly&&a):ZPoly(){fmpz_poly_swap(p,a.p);}ZPoly&operator=(ZPoly a){fmpz_poly_swap(p,a.p);return *this;}~ZPoly(){fmpz_poly_clear(p);}};
void writeMatrix(const vector<vector<Poly>>&A,const string&path){ofstream o(path);assert(o.is_open());int n=A.size();o<<n<<' '<<n<<'\n';fmpq_t q;fmpq_init(q);for(auto&r:A){int nn=0;for(auto&a:r)nn+=!fmpq_poly_is_zero(a.p);o<<nn<<'\n';for(int j=0;j<n;j++)if(!fmpq_poly_is_zero(r[j].p)){o<<j<<'\n';int ct=0;for(int k=0;k<fmpq_poly_length(r[j].p);k++){fmpq_poly_get_coeff_fmpq(q,r[j].p,k);ct+=!fmpq_is_zero(q);}o<<ct;for(int k=0;k<fmpq_poly_length(r[j].p);k++){fmpq_poly_get_coeff_fmpq(q,r[j].p,k);if(fmpq_is_zero(q))continue;char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s<<" 0 "<<k;flint_free(s);}o<<'\n';}}fmpq_clear(q);o.flush();assert(o.good());}
int main(int argc,char**argv){assert(argc==4);ifstream in(argv[1]);assert(in.is_open());int n,m;in>>n>>m;assert(n==m);vector<vector<Poly>>A(n,vector<Poly>(n));fmpq_t q;fmpq_init(q);for(int i=0;i<n;i++){int nn;in>>nn;for(int z=0;z<nn;z++){int j,ct;in>>j>>ct;for(int k=0;k<ct;k++){string s;int e,d;in>>s>>e>>d;assert(e==0&&d>=0);assert(!fmpq_set_str(q,s.c_str(),10));fmpq_canonicalise(q);fmpq_poly_set_coeff_fmpq(A[i][j].p,d,q);}}}assert(in.good());int limit=stoi(argv[2]),valuation=0;string prefix=argv[3];ofstream meta(prefix+".meta");assert(meta.is_open());auto start=chrono::steady_clock::now();for(int stage=0;stage<limit;stage++){fmpq_mat_t L,R;fmpq_mat_init(L,n,n);fmpq_mat_init(R,n,n);for(int i=0;i<n;i++)for(int j=0;j<n;j++)fmpq_poly_get_coeff_fmpq(fmpq_mat_entry(L,i,j),A[i][j].p,0);int rank=fmpq_mat_rref(R,L),k=n-rank;cerr<<"STAGE "<<stage<<" RANK "<<rank<<" CORANK "<<k<<" VALUATION "<<valuation<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';meta<<stage<<' '<<rank<<' '<<k<<' '<<valuation<<'\n';meta.flush();if(!k){fmpq_mat_clear(L);fmpq_mat_clear(R);break;}vector<int>piv,free;vector<bool>used(n);for(int i=0;i<rank;i++){int j=0;while(j<n&&fmpq_is_zero(fmpq_mat_entry(R,i,j)))j++;assert(j<n&&fmpq_is_one(fmpq_mat_entry(R,i,j)));piv.push_back(j);used[j]=1;}for(int j=0;j<n;j++)if(!used[j])free.push_back(j);assert((int)free.size()==k);fmpq_mat_t K,check;fmpq_mat_init(K,n,k);fmpq_mat_init(check,n,k);for(int a=0;a<k;a++){fmpq_one(fmpq_mat_entry(K,free[a],a));for(int i=0;i<rank;i++)fmpq_neg(fmpq_mat_entry(K,piv[i],a),fmpq_mat_entry(R,i,free[a]));}fmpq_mat_mul(check,L,K);assert(fmpq_mat_is_zero(check));ofstream ko(prefix+".kernel"+to_string(stage));assert(ko.is_open());ko<<n<<" 0 "<<k<<'\n';for(int a=0;a<k;a++){int nn=0;for(int j=0;j<n;j++)nn+=!fmpq_is_zero(fmpq_mat_entry(K,j,a));ko<<nn;for(int j=0;j<n;j++)if(!fmpq_is_zero(fmpq_mat_entry(K,j,a))){char*s=fmpq_get_str(nullptr,10,fmpq_mat_entry(K,j,a));ko<<' '<<j<<' '<<s;flint_free(s);}ko<<'\n';}ko.flush();assert(ko.good());vector<vector<Poly>>B(n,vector<Poly>(n));vector<Z>rd(n),kd(k);vector<vector<Z>>kz(n,vector<Z>(k));vector<vector<ZPoly>>az(n,vector<ZPoly>(n));Z denominator,ratio;for(int i=0;i<n;i++){fmpz_one(rd[i].v);for(int j=0;j<n;j++)if(!fmpq_poly_is_zero(A[i][j].p)){fmpq_poly_get_denominator(denominator.v,A[i][j].p);fmpz_lcm(rd[i].v,rd[i].v,denominator.v);}for(int j=0;j<n;j++)if(!fmpq_poly_is_zero(A[i][j].p)){fmpq_poly_get_denominator(denominator.v,A[i][j].p);fmpz_divexact(ratio.v,rd[i].v,denominator.v);fmpq_poly_get_numerator(az[i][j].p,A[i][j].p);fmpz_poly_scalar_mul_fmpz(az[i][j].p,az[i][j].p,ratio.v);}}for(int a=0;a<k;a++){fmpz_one(kd[a].v);for(int j=0;j<n;j++)fmpz_lcm(kd[a].v,kd[a].v,fmpq_denref(fmpq_mat_entry(K,j,a)));for(int j=0;j<n;j++){fmpz_divexact(ratio.v,kd[a].v,fmpq_denref(fmpq_mat_entry(K,j,a)));fmpz_mul(kz[j][a].v,ratio.v,fmpq_numref(fmpq_mat_entry(K,j,a)));}}for(int i=0;i<n;i++){for(int j=0;j<rank;j++)B[i][j]=A[i][piv[j]];for(int a=0;a<k;a++){ZPoly sum;for(int j=0;j<n;j++)if(!fmpz_is_zero(kz[j][a].v)&&!fmpz_poly_is_zero(az[i][j].p))fmpz_poly_scalar_addmul_fmpz(sum.p,az[i][j].p,kz[j][a].v);fmpz_poly_get_coeff_fmpz(ratio.v,sum.p,0);assert(fmpz_is_zero(ratio.v));fmpz_poly_shift_right(sum.p,sum.p,1);fmpq_poly_set_fmpz_poly(B[i][rank+a].p,sum.p);fmpz_mul(denominator.v,rd[i].v,kd[a].v);fmpq_poly_scalar_div_fmpz(B[i][rank+a].p,B[i][rank+a].p,denominator.v);}}
A=std::move(B);valuation+=k;cerr<<"PEEL_PASS "<<k<<" TOTAL "<<valuation<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';fmpq_mat_clear(K);fmpq_mat_clear(check);fmpq_mat_clear(L);fmpq_mat_clear(R);assert(chrono::duration<double>(chrono::steady_clock::now()-start).count()<120);}writeMatrix(A,prefix+".full");meta<<"TOTAL "<<valuation<<"\nSECONDS "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';meta.flush();assert(meta.good());fmpq_clear(q);flint_cleanup();}
